<?php
declare(strict_types=1);
namespace KodVadAll\Modules\Data;
use PDO;
use RuntimeException;
use Throwable;
final class DataController
{
 public static function handle(PDO $db,array $admin):void
 {
  kd_require_permission('data.view');$errors=[];$success='';
  if($_SERVER['REQUEST_METHOD']==='POST'){kd_csrf_check();kd_require_permission('data.manage');try{$entity=(string)($_POST['entity']??'');if(!in_array($entity,['customers','products'],true))throw new RuntimeException('Desteklenmeyen veri türü.');$file=$_FILES['csv']??null;if(!is_array($file)||($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||(int)$file['size']>10*1024*1024)throw new RuntimeException('10 MB sınırında geçerli bir CSV dosyası seçin.');$h=fopen($file['tmp_name'],'rb');if(!$h)throw new RuntimeException('CSV dosyası okunamadı.');$first=fgets($h);if($first===false)throw new RuntimeException('CSV dosyası boş.');$delimiter=substr_count($first,';')>substr_count($first,',')?';':',';rewind($h);$header=fgetcsv($h,0,$delimiter,'"','');if(!$header)throw new RuntimeException('CSV başlık satırı bulunamadı.');$header=array_map(static fn($v)=>strtolower(trim((string)$v)), $header);$header[0]=preg_replace('/^\\xEF\\xBB\\xBF/','',$header[0]??'');$required=$entity==='customers'?['name']:['name','sale_price'];foreach($required as $field)if(!in_array($field,$header,true))throw new RuntimeException('CSV içinde zorunlu sütun eksik: '.$field);
    $total=0;$ok=0;$failed=0;$rowErrors=[];$db->beginTransaction();while(($row=fgetcsv($h,0,$delimiter,'"',''))!==false){if(count($row)===1&&trim((string)$row[0])==='')continue;$total++;if($total>5000){$failed++;$rowErrors[]='En fazla 5.000 satır içe aktarılabilir.';break;}$data=[];foreach($header as $i=>$key)$data[$key]=trim((string)($row[$i]??''));try{
     if($entity==='customers'){$name=$data['name']??'';$email=$data['email']??'';if($name===''||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL)))throw new RuntimeException('Ad veya e-posta geçersiz.');$code=trim($data['customer_code']??'');$type=in_array($data['type']??'', ['individual','company'],true)?$data['type']:'individual';$status=in_array($data['status']??'', ['active','inactive'],true)?$data['status']:'active';$values=[$type,$name,$email?:null,$data['phone']??null,$data['tax_number']??null,$data['notes']??null,$status];if($code!==''){$q=$db->prepare('SELECT id FROM customers WHERE customer_code=?');$q->execute([$code]);$id=(int)$q->fetchColumn();if($id){$db->prepare('UPDATE customers SET type=?,name=?,email=?,phone=?,tax_number=?,notes=?,status=?,updated_at=NOW() WHERE id=?')->execute([...$values,$id]);}else{$db->prepare('INSERT INTO customers (customer_code,type,name,email,phone,tax_number,notes,status,created_at) VALUES (?,?,?,?,?,?,?,?,NOW())')->execute([$code,...$values]);}}else{$db->prepare('INSERT INTO customers (customer_code,type,name,email,phone,tax_number,notes,status,created_at) VALUES (NULL,?,?,?,?,?,?,?,NOW())')->execute($values);}}
     else{$name=$data['name']??'';$sku=trim($data['sku']??'');$sale=(float)($data['sale_price']??0);$purchase=(float)($data['purchase_price']??0);$stock=(float)($data['stock_quantity']??0);$taxRate=(float)($data['tax_rate']??20);if($name===''||$sale<0||$purchase<0||$stock<0||$taxRate<0||$taxRate>100)throw new RuntimeException('Ürün adı, fiyat, stok veya KDV oranı geçersiz.');$values=[$name,$data['description']??null,$purchase,$sale,$stock,trim($data['unit']??'Adet')?:'Adet',max(0,(float)($data['min_stock']??0)),in_array($data['track_stock']??'1',['1','true','yes'],true)?1:0,$taxRate,in_array($data['status']??'', ['active','inactive'],true)?$data['status']:'active'];if($sku!==''){$q=$db->prepare('SELECT id,stock_quantity FROM products WHERE sku=?');$q->execute([$sku]);$existing=$q->fetch();$id=(int)($existing['id']??0);if($id){$before=(float)$existing['stock_quantity'];$after=(float)$values[4];$db->prepare('UPDATE products SET name=?,description=?,purchase_price=?,sale_price=?,stock_quantity=?,unit=?,min_stock=?,track_stock=?,tax_rate=?,status=?,updated_at=NOW() WHERE id=?')->execute([...$values,$id]);if($after!==$before)$db->prepare('INSERT INTO product_stock_movements (product_id,user_id,movement_type,quantity,before_quantity,after_quantity,note,created_at) VALUES (?,? ,\'adjustment\',?,?,?,?,NOW())')->execute([$id,(int)$admin['id'],abs($after-$before),$before,$after,'CSV içe aktarma stok düzeltmesi']);}else{$db->prepare('INSERT INTO products (sku,name,description,purchase_price,sale_price,stock_quantity,unit,min_stock,track_stock,tax_rate,status,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,NOW())')->execute([$sku,...$values]);$id=(int)$db->lastInsertId();if((float)$values[4]>0)$db->prepare('INSERT INTO product_stock_movements (product_id,user_id,movement_type,quantity,before_quantity,after_quantity,note,created_at) VALUES (?,? ,\'opening\',?,0,?,?,NOW())')->execute([$id,(int)$admin['id'],(float)$values[4],(float)$values[4],'CSV içe aktarma açılış stoğu']);}}else{$db->prepare('INSERT INTO products (sku,name,description,purchase_price,sale_price,stock_quantity,unit,min_stock,track_stock,tax_rate,status,created_at) VALUES (NULL,?,?,?,?,?,?,?,?,?,?,NOW())')->execute($values);}}
     $ok++;
    }catch(Throwable $e){$failed++;if(count($rowErrors)<30)$rowErrors[]='Satır '.($total+1).': '.$e->getMessage();}}
    fclose($h);$db->commit();$db->prepare('INSERT INTO data_transfer_logs (user_id,transfer_type,entity,file_name,rows_total,rows_success,rows_failed,details_json,created_at) VALUES (?,?,?,?,?,?,?,?,NOW())')->execute([(int)$admin['id'],'import',$entity,basename((string)$file['name']),$total,$ok,$failed,json_encode($rowErrors,JSON_UNESCAPED_UNICODE)]);$success=$ok.' satır aktarıldı, '.$failed.' satır hatalı.';if($rowErrors)$errors=$rowErrors;
   }catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('KodVadAll data import: '.$e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'CSV içe aktarma tamamlanamadı.';}}
  $logs=$db->query('SELECT * FROM data_transfer_logs ORDER BY id DESC LIMIT 30')->fetchAll();$pageTitle='Veri İçe / Dışa Aktarma';ob_start();require KD_ROOT.'/app/Views/data/index.php';$content=ob_get_clean();require KD_ROOT.'/app/Views/layouts/admin.php';
 }
}
